package com.astarworks.astera.core.domain.region

/**
 * Vendor-neutral identifier for a [com.astarworks.astera.core.domain.stage.Region]
 * **within a permission / spatial-index context**.
 *
 * `Region` itself is intentionally id-less (it is pure geometry). Permission
 * rules and spatial-index entries are keyed by `RegionId`, which is assigned
 * by the stage author (YAML key) or generated by an indexer.
 *
 * Wave 5n (ADR-0092) introduces this so [com.astarworks.astera.core.application.port.outbound.IRegionPermissionService]
 * has a stable handle that survives region re-indexing.
 */
@JvmInline
public value class RegionId(public val value: String) {
    init {
        require(value.isNotBlank()) { "RegionId must not be blank" }
        require(VALID.matches(value)) {
            "RegionId must be lower-kebab-case (a-z, 0-9, -, _): '$value'"
        }
    }

    override fun toString(): String = value

    public companion object {
        private val VALID = Regex("^[a-z0-9][a-z0-9_-]*$")
    }
}
